mapper.select:
SELECT COUNT(*) AS count
FROM shelf
WHERE shelf_no = #{shelfNo}

    AND id != #{excludeId}

mapper.update:
UPDATE shelf
SET status = #{status},
    update_time = #{updateTime}
WHERE id = #{id}
  AND deleted = 0

UPDATE shelf
SET deleted = 1,
    update_time = #{updateTime}
WHERE id = #{id}
  AND deleted = 0

UPDATE shelf
SET capacity = capacity + 1,
    update_time = #{updateTime}
WHERE id = #{id}
  AND deleted = 0

UPDATE shelf
SET capacity = capacity - 1,
    update_time = #{updateTime}
WHERE id = #{id}
  AND deleted = 0

UPDATE shelf
SET used_count = (SELECT COUNT(*) FROM shelf_location
                  WHERE shelf_id = #{id} AND used_count > 0),
    update_time = #{updateTime}
WHERE id = #{id}
  AND deleted = 0
